/**
 * Generates src/types/api/enums.ts from apps/api/prisma/schema.prisma.
 *
 * Mirrors every real Prisma `enum` as a string-literal union (`as const` array +
 * derived type, per code-standards.md §1 — no TS `enum`). Parses the schema directly
 * rather than hand-typing values, per architecture.md §10's explicit rule.
 *
 * Usage: pnpm -F @societyledger/mobile gen:enums [--check]
 *   --check  exit 1 if the generated file would differ from what's on disk, without writing.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';

const SCHEMA_PATH = resolve(__dirname, '../../api/prisma/schema.prisma');
const OUTPUT_PATH = resolve(__dirname, '../src/types/api/enums.ts');

type ParsedEnum = { name: string; values: string[] };

function parseEnums(schema: string): ParsedEnum[] {
  const enums: ParsedEnum[] = [];
  const enumBlockPattern = /enum\s+(\w+)\s*\{([^}]*)\}/g;
  let match: RegExpExecArray | null;

  while ((match = enumBlockPattern.exec(schema)) !== null) {
    const [, name, body] = match;
    if (!name || body === undefined) continue;

    const values = body
      .split('\n')
      .map((line) => line.replace(/\/\/.*$/, '').trim())
      .filter((line) => line.length > 0)
      .map((line) => {
        const token = line.match(/^(\w+)/);
        if (!token) {
          throw new Error(`Unparseable enum value line in "${name}": "${line}"`);
        }
        return token[1]!;
      });

    if (values.length === 0) {
      throw new Error(`Enum "${name}" parsed with zero values — check schema.prisma`);
    }

    enums.push({ name, values });
  }

  if (enums.length === 0) {
    throw new Error(`No enums found in ${SCHEMA_PATH} — check the schema path/format`);
  }

  return enums;
}

function renderFile(enums: ParsedEnum[]): string {
  const header = `/**
 * GENERATED by scripts/gen-enums.ts from apps/api/prisma/schema.prisma — do not edit by hand.
 * Run \`pnpm -F @societyledger/mobile gen:enums\` to regenerate after a schema change.
 *
 * Every export is a string-literal union, mirroring the real Prisma enum value set exactly
 * (architecture.md §10). Free-form \`String\` columns that happen to hold enum-like values
 * (e.g. Member.status) are NOT Prisma enums and are deliberately not included here.
 */
/* eslint-disable @typescript-eslint/no-redeclare -- each pair below is a deliberate const+type merge (code-standards.md §1), not a real redeclaration */
`;

  const body = enums
    .map(({ name, values }) => {
      const arrayLiteral = values.map((v) => `'${v}'`).join(', ');
      return `export const ${name} = [${arrayLiteral}] as const;\nexport type ${name} = (typeof ${name})[number];`;
    })
    .join('\n\n');

  return `${header}\n${body}\n`;
}

function main() {
  const checkOnly = process.argv.includes('--check');

  if (!existsSync(SCHEMA_PATH)) {
    console.error(`Schema not found at ${SCHEMA_PATH}`);
    process.exit(1);
  }

  const schema = readFileSync(SCHEMA_PATH, 'utf-8');
  const enums = parseEnums(schema);
  const generated = renderFile(enums);

  const existing = existsSync(OUTPUT_PATH) ? readFileSync(OUTPUT_PATH, 'utf-8') : null;
  const unchanged = existing === generated;

  if (checkOnly) {
    if (unchanged) {
      console.log(`gen:enums --check: up to date (${enums.length} enums).`);
      process.exit(0);
    }
    console.error(
      `gen:enums --check: ${OUTPUT_PATH} is out of date with schema.prisma. Run "pnpm -F @societyledger/mobile gen:enums" and commit the result.`
    );
    process.exit(1);
  }

  if (unchanged) {
    console.log(`gen:enums: ${enums.length} enums, no changes.`);
    return;
  }

  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  writeFileSync(OUTPUT_PATH, generated, 'utf-8');
  console.log(`gen:enums: wrote ${enums.length} enums to ${OUTPUT_PATH}.`);
}

main();
